def shapes(g):
    from collections import defaultdict
    cells=defaultdict(list)
    for i,r in enumerate(g):
        for j,v in enumerate(r):
            if v: cells[v].append((i,j))
    sh={}
    for c,pts in cells.items():
        S=set(pts); comps=[]
        while S:
            p=next(iter(S)); st=[p]; comp=[]
            while st:
                q=st.pop()
                if q in S: S.discard(q); comp.append(q)
                st+=[(q[0]+a,q[1]+b) for a,b in((1,0),(-1,0),(0,1),(0,-1))]
            comps.append(comp)
        sh[c]=[]
        for comp in comps:
            a=min(p[0] for p in comp); b=min(p[1] for p in comp)
            sh[c].append(sorted((p[0]-a,p[1]-b) for p in comp))
    return sh
def f(g):
    sh=shapes(g)
    order=sorted(sh, key=lambda c: sum(len(s) for s in sh[c]))
    out=[[0]*len(g[0]) for _ in g]
    x=0; H=len(g)
    for c in order:
        ss=sorted(sh[c], key=len)
        w=max(max(p[1] for p in s) for s in ss)+1
        rows=[]; h=0
        for s in ss:
            if rows: rows.append(None); h+=1
            rows.append(s); h+=max(p[0] for p in s)+1
        r=H-h
        for s in rows:
            if s is None: r+=1; continue
            for p in s: out[r+p[0]][x+p[1]]=c
            r+=max(p[0] for p in s)+1
        x+=w+1
    return out
